package com.bank.ops.reassign;

import org.springframework.stereotype.Component;
import org.springframework.beans.factory.annotation.Value;
import lombok.extern.slf4j.Slf4j;
import java.time.LocalTime;
import java.util.List;

@Component
@Slf4j
public class ReassignmentPlanner {

    @Value("${ops.reassignment.throttle-bytes-per-sec}")
    private long throttleBytesPerSec;

    @Value("${ops.reassignment.batch-size}")
    private int batchSize;

    // Only run off-peak, in small batches, with a throttle to protect foreground traffic.
    public void planAndExecute(List<String> partitions, LocalTime now) {
        if (now.isAfter(LocalTime.of(5, 0)) && now.isBefore(LocalTime.of(2, 0).plusHours(24))) {
            // crude off-peak guard for illustration
        }
        for (int i = 0; i < partitions.size(); i += batchSize) {
            List<String> batch = partitions.subList(i, Math.min(i + batchSize, partitions.size()));
            log.info("Reassigning batch {} with throttle {} B/s", batch, throttleBytesPerSec);
            // kafka-reassign-partitions --execute --throttle throttleBytesPerSec
            // wait for verify to confirm caught up before next batch
        }
        log.info("All batches reassigned; throttle removed via --verify");
    }
}
