package com.bank.ops.demo;

import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class ReassignmentDemo {

    private static final Logger log = Logger.getLogger(ReassignmentDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        ReassignmentSimulator sim = new ReassignmentSimulator();

        log.info("=== Unthrottled, during PEAK traffic (bad) ===");
        sim.run(List.of("settle-0", "settle-1", "settle-2", "settle-3"),
                /*throttleMBps*/ 0, /*peak*/ true, log);

        log.info("=== Throttled 50 MB/s, OFF-PEAK, small batches (good) ===");
        sim.run(List.of("settle-0", "settle-1", "settle-2", "settle-3"),
                /*throttleMBps*/ 50, /*peak*/ false, log);
    }
}

// ─── Would be in Broker.java in a real project ───
class Broker {
    final String name;
    int cacheWarmth = 100; // percent; 0 = cold
    Broker(String name) { this.name = name; }
    void receiveReplica() { cacheWarmth = 0; } // cold after a move
    void warm(int pct) { cacheWarmth = Math.min(100, cacheWarmth + pct); }
}

// ─── Would be in Partition.java in a real project ───
class Partition {
    final String name;
    final int sizeMB;
    Partition(String name, int sizeMB) { this.name = name; this.sizeMB = sizeMB; }
}

// ─── Would be in ReassignmentPlan.java in a real project ───
class ReassignmentPlan {
    final List<Partition> partitions;
    ReassignmentPlan(List<Partition> partitions) { this.partitions = partitions; }
}

// ─── Would be in ReassignmentSimulator.java in a real project ───
class ReassignmentSimulator {

    void run(List<String> partitionNames, int throttleMBps, boolean peak, Logger log) {
        int totalMB = partitionNames.size() * 4000; // 4 GB each
        int foregroundHeadroomMBps = peak ? 20 : 200; // spare I/O depends on traffic

        // Cause 1 & 2: copy rate vs duration
        int copyRate = throttleMBps == 0 ? 400 : throttleMBps; // uncapped saturates links
        int contention = Math.max(0, copyRate - foregroundHeadroomMBps);
        int durationSec = totalMB / copyRate;

        // Cause 3: leader moves cause NOT_LEADER_FOR_PARTITION + metadata refresh
        int leaderMoves = partitionNames.size();
        // Cause 4: cold cache penalty after each move
        Broker dest = new Broker("kafka-new-1");
        dest.receiveReplica();
        int coldCacheLatencyMs = (100 - dest.cacheWarmth) / 2; // worse while cold
        // Cause 5: coordination churn scales with simultaneous moves
        int coordinationChurn = peak ? leaderMoves * 3 : leaderMoves;

        int lagSpike = contention * 10 + leaderMoves * 50 + coldCacheLatencyMs * 5 + coordinationChurn * 10;

        if (lagSpike > 2000) {
            log.severe(String.format(
                "LAG SPIKE=%d msgs over %ds | contention=%dMB/s leaderMoves=%d coldCacheMs=%d churn=%d",
                lagSpike, durationSec, contention, leaderMoves, coldCacheLatencyMs, coordinationChurn));
        } else {
            log.info(String.format(
                "contained lag=%d msgs over %ds | contention=%dMB/s leaderMoves=%d coldCacheMs=%d churn=%d",
                lagSpike, durationSec, contention, leaderMoves, coldCacheLatencyMs, coordinationChurn));
        }
        log.info("Note: throttle lowers contention but increases duration ("
                + durationSec + "s) — trade rate for duration");
    }
}

